-- Apply only after the snapshot-aware speed-v3 backend is live and verified.
BEGIN;
LOCK TABLE multigame.daily_challenges, multigame.daily_attempts IN SHARE ROW EXCLUSIVE MODE;
DO $$ BEGIN
 IF to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD') <> '2026-11-03' THEN RAISE EXCEPTION 'Cutover date has changed'; END IF;
 IF EXISTS(SELECT 1 FROM multigame.daily_attempts WHERE day='2026-11-03' AND ranked=1) THEN RAISE EXCEPTION 'Ranked attempts exist; preserve this event until reset'; END IF;
 IF NOT EXISTS(SELECT 1 FROM multigame.daily_challenges WHERE day='2026-11-03' AND status='published') THEN RAISE EXCEPTION 'Expected published challenge missing'; END IF;
END $$;
-- Freeze any old practice starts created since the additive migration.
UPDATE multigame.daily_attempts a SET challenge_snapshot=jsonb_build_object('day',c.day,'version',c.version,'title',c.title,'questions',c.questions,'status',c.status,'scoring_version',c.scoring_version)::text FROM multigame.daily_challenges c WHERE a.day=c.day AND a.day='2026-11-03' AND a.challenge_snapshot IS NULL;
UPDATE multigame.daily_challenges SET version=3,scoring_version='daily-speed-v3',questions='[{"id":"fact-oxygen-number","question":"What is the atomic number of oxygen?","options":["10","8","11","9"],"answer":1,"category":"Numbers","difficulty":"easy","sourceUrl":"https://periodic-table.rsc.org/element/8/oxygen","explanation":"The Royal Society of Chemistry lists atomic number 8.","mode":"crack"},{"id":"fact-gold-purity","question":"How many carats describe pure gold?","options":["32","24","17","41"],"answer":1,"category":"Numbers","difficulty":"easy","sourceUrl":"https://periodic-table.rsc.org/element/79/Gold","explanation":"Pure gold is 24-carat gold.","mode":"draw"},{"id":"fact-saturn-diameter","question":"About how many kilometres across is Saturn at its equator?","options":["84375","120536","192861","156698"],"answer":1,"category":"Numbers","difficulty":"challenging","sourceUrl":"https://science.nasa.gov/solar-system/planet-sizes-and-locations-in-our-solar-system/","explanation":"NASA gives 120,536 km for the equatorial diameter.","mode":"size_it_up"},{"id":"flamenco-heartland","question":"Which region of Spain is the heartland of flamenco?","options":["Galicia","Catalonia","Andalusia","Navarre"],"answer":2,"category":"Music","difficulty":"medium","sourceUrl":"https://ich.unesco.org/en/RL/flamenco-00363","explanation":"Andalusia. See the linked primary source.","mode":"claw"},{"id":"mariachi-bass","question":"Which large bass guitar is part of modern mariachi?","options":["Mandolin","Balalaika","Sitar","Guitarrón"],"answer":3,"category":"Music","difficulty":"challenging","sourceUrl":"https://ich.unesco.org/en/RL/mariachi-string-music-song-and-trumpet-00575","explanation":"Guitarrón. See the linked primary source.","mode":"drop"}]',prepared_at=to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') WHERE day='2026-11-03';
COMMIT;
